using System;
using System.Collections.Generic;
using Framework.Parameters;

namespace Game.AI.Parameters
{
    /// <summary>
    /// 迷路内の敵が使用する共通パラメーター定義を管理する。
    /// </summary>
    /// <remarks>
    /// 定義は全エージェントで共有する。
    /// 実行時のパラメーターはエージェントごとに生成する。
    /// </remarks>
    public static class MazeEnemyParameterCatalog
    {
        /// <summary>
        /// すべての共通パラメーター定義。
        /// </summary>
        private static readonly
            ParameterDefinition<MazeEnemyParameter>[] definitions =
        {
            // 基本能力
            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.MoveSpeed,
                3.5f, 0f, 12f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.ChaseSpeedMultiplier,
                1.15f, 0f, 3f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.EscapeSpeedMultiplier,
                1.3f, 0f, 3f),

            // 認識能力
            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.DetectionRange,
                6f, 0f, 64f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.ThreatDetectionRange,
                8f, 0f, 64f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.MemoryDuration,
                5f, 0f, 60f),
       
            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.HearingRange,
                8f, 0f, 64f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.HearingSensitivity,
                0.5f, 0f, 1f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.HearingAccuracy,
                0.5f, 0f, 1f),

            // 性格
            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.Aggression,
                0.5f, 0f, 1f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.Caution,
                0.5f, 0f, 1f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.Persistence,
                0.5f, 0f, 1f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.TacticalIntelligence,
                0.3f, 0f, 1f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.Territoriality,
                0.3f, 0f, 1f),

            // 行動傾向
            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.Exploration,
                0.5f, 0f, 1f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.PatrolPreference,
                0.5f, 0f, 1f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.TerritoryRadius,
                5f, 0f, 64f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.VisitMemoryDuration,
                30f, 0f, 300f),

            new ParameterDefinition<MazeEnemyParameter>(
                MazeEnemyParameter.PredictionTime,
                1f, 0f, 5f)
        };

        /// <summary>
        /// 外部から変更できないパラメーター定義一覧。
        /// </summary>
        private static readonly
            IReadOnlyList<ParameterDefinition<MazeEnemyParameter>>
            readOnlyDefinitions =
                Array.AsReadOnly(definitions);

        /// <summary>
        /// 識別子による定義検索用の辞書。
        /// </summary>
        private static readonly Dictionary<
            MazeEnemyParameter,
            ParameterDefinition<MazeEnemyParameter>>
            definitionMap = CreateDefinitionMap();

        /// <summary>
        /// 登録されているパラメーター定義数。
        /// </summary>
        public static int Count => definitions.Length;

        /// <summary>
        /// すべてのパラメーター定義を取得する。
        /// </summary>
        public static IReadOnlyList<ParameterDefinition<MazeEnemyParameter>>
            Definitions => readOnlyDefinitions;

        /// <summary>
        /// 指定されたパラメーターが定義されているか確認する。
        /// </summary>
        /// <param name="id">パラメーター識別子</param>
        /// <returns>定義されている場合はtrue</returns>
        public static bool Contains(MazeEnemyParameter id)
        {
            return definitionMap.ContainsKey(id);
        }

        /// <summary>
        /// 指定されたパラメーター定義を取得する。
        /// </summary>
        /// <param name="id">パラメーター識別子</param>
        /// <param name="definition">取得した定義</param>
        /// <returns>取得に成功した場合はtrue</returns>
        public static bool TryGetDefinition(
            MazeEnemyParameter id,
            out ParameterDefinition<MazeEnemyParameter> definition)
        {
            return definitionMap.TryGetValue(
                id, out definition);
        }

        /// <summary>
        /// 指定されたパラメーター定義を取得する。
        /// </summary>
        /// <param name="id">パラメーター識別子</param>
        /// <returns>対応するパラメーター定義</returns>
        /// <exception cref="KeyNotFoundException">
        /// 指定された識別子が存在しない場合に発生する。
        /// </exception>
        public static ParameterDefinition<MazeEnemyParameter>
            GetDefinition(MazeEnemyParameter id)
        {
            if (!TryGetDefinition(id, out var definition))
            {
                throw new KeyNotFoundException(
                    $"敵パラメーターが定義されていません：{id}");
            }

            return definition;
        }

        /// <summary>
        /// 標準値を使用した実行時パラメーターセットを生成する。
        /// </summary>
        /// <returns>独立した実行時パラメーターセット</returns>
        public static ParameterSet<MazeEnemyParameter>
            CreateParameterSet()
        {
            return new ParameterSet<MazeEnemyParameter>(
                definitions);
        }

        /// <summary>
        /// 識別子による検索用辞書を生成する。
        /// </summary>
        /// <returns>パラメーター定義の辞書</returns>
        private static Dictionary<
            MazeEnemyParameter,
            ParameterDefinition<MazeEnemyParameter>>
            CreateDefinitionMap()
        {
            var map = new Dictionary<
                MazeEnemyParameter,
                ParameterDefinition<MazeEnemyParameter>>();

            foreach (var definition in definitions)
            {
                map.Add(definition.Id, definition);
            }

            return map;
        }
    }
}
